# Enum values for a `do` method token and param flag, keyed "token::--flag".
__homelink_param_values() {
    case "$1::$2" in
        SpeakerHub.playAudio::--tone|playAudio::--tone) echo "Alert Emergency Tip Warn" ;;
        LeakSensor.setSettings::--sensorMode|setSettings::--sensorMode) echo "WaterLeak WaterPeak" ;;
        Thermostat.setState::--mode|setState::--mode) echo "auto cool heat off" ;;
        IPCamera.setProperties::--nightVision|setProperties::--nightVision) echo "auto off on" ;;
        Thermostat.setState::--fan|setState::--fan) echo "auto on" ;;
        setState::--state) echo "close locked open unlocked" ;;
        Dimmer.setState::--state|Manipulator.setState::--state|MultiOutlet.setState::--state|Outlet.setState::--state|Switch.setState::--state|WaterLeakController.setState::--valve|WaterMeterController.setState::--valve|setState::--valve) echo "close open" ;;
        COSmokeSensor.setSchedule::--`type`|setSchedule::--`type`) echo "disable monthly weekly" ;;
        LeakSensor.setSettings::--sensitivity|setSettings::--sensitivity) echo "high low" ;;
        Thermostat.setState::--sche|setState::--sche) echo "hold run" ;;
        LockV2.setAttributes::--rlSet|setAttributes::--rlSet) echo "left right" ;;
        Thermostat.setProperties::--master|setProperties::--master) echo "local sensor1 sensor2" ;;
        Lock.setState::--state) echo "locked unlocked" ;;
        SprinklerV2.setState::--waterMode|setState::--waterMode) echo "manual schedule" ;;
        IPCamera.setProperties::--indicatorLight|IPCamera.setProperties::--voicePrompts|Thermostat.setECO::--mode|setECO::--mode|setProperties::--indicatorLight|setProperties::--voicePrompts) echo "off on" ;;
        Sprinkler.setManualWater::--state|setManualWater::--state) echo "start stop" ;;
        *) echo "" ;;
    esac
}

_homelink() {
    local cur prev
    cur="${COMP_WORDS[COMP_CWORD]}"
    prev="${COMP_WORDS[COMP_CWORD-1]}"

    # Values of global flags, wherever they appear.
    case "$prev" in
        --log)
            COMPREPLY=( $(compgen -W "$__homelink_log_levels" -- "$cur") )
            return ;;
        --output)
            COMPREPLY=( $(compgen -W "$__homelink_output_formats" -- "$cur") )
            return ;;
        --client-id|--client-secret)
            return ;;  # free-form secret; nothing to suggest
    esac

    # Locate the subcommand: the first recognised command word.
    local i cmd="" cmd_idx=-1
    for (( i=1; i < COMP_CWORD; i++ )); do
        case "${COMP_WORDS[i]}" in
            ls|listen|do|help) cmd="${COMP_WORDS[i]}"; cmd_idx=$i; break ;;
        esac
    done

    # Before the subcommand: complete the global flag or the command list.
    if [[ -z "$cmd" ]]; then
        if [[ "$cur" == -* ]]; then
            COMPREPLY=( $(compgen -W "$__homelink_global_flags" -- "$cur") )
        else
            COMPREPLY=( $(compgen -W "$__homelink_commands" -- "$cur") )
        fi
        return
    fi

    case "$cmd" in
        listen)
            [[ "$prev" == "--on" ]] && return  # device name is a runtime value; nothing to offer
            COMPREPLY=( $(compgen -W "--on" -- "$cur") )
            ;;
        do)
            local method_idx=$((cmd_idx + 1))
            # The method is the first word after `do`; complete names and type prefixes there.
            if (( COMP_CWORD == method_idx )); then
                COMPREPLY=( $(compgen -W "$__homelink_methods" -- "$cur") )
                return
            fi
            [[ "$prev" == "--on" ]] && return  # device name is a runtime value

            local method="${COMP_WORDS[method_idx]}"
            # After a param flag, offer its enum values when the API documents them.
            if [[ "$prev" == --* && "$prev" != "--on" ]]; then
                local choices
                choices="$(__homelink_param_values "$method" "$prev")"
                if [[ -n "$choices" ]]; then
                    COMPREPLY=( $(compgen -W "$choices" -- "$cur") )
                    return
                fi
            fi
            # Otherwise offer --on and this method's param flags.
            COMPREPLY=( $(compgen -W "--on $(__homelink_method_params "$method")" -- "$cur") )
            ;;
    esac
}

complete -F _homelink homelink
